import json
from pathlib import Path

CONFIG_FILE = Path.home() / '.codewriter_config.json'

def load_config():
    if CONFIG_FILE.exists():
        with open(CONFIG_FILE, 'r') as f:
            return json.load(f)
    return {'is_configured': False}

def save_config(config):
    with open(CONFIG_FILE, 'w') as f:
        json.dump(config, f, indent=2)
    print(f"Configuration saved to {CONFIG_FILE}")  # Debug print

import streamlit as st
from pathlib import Path
import json
from utils import ollama_api

def save_plan_to_file(plan, project_path):
    plan_file = project_path / "project_plan.json"
    with open(plan_file, "w") as f:
        json.dump(plan, f, indent=2)

def load_plan_from_file(project_path):
    plan_file = project_path / "project_plan.json"
    if plan_file.exists():
        with open(plan_file, "r") as f:
            return json.load(f)
    return None

def save_project_details(details, project_path):
    details_file = project_path / "project_details.json"
    with open(details_file, "w") as f:
        json.dump(details, f, indent=2)

def load_project_details(project_path):
    details_file = project_path / "project_details.json"
    if details_file.exists():
        with open(details_file, "r") as f:
            return json.load(f)
    return {
        'type': '', 'description': '', 'audience': '', 'features': '',
        'ui': '', 'storage': '', 'apis': '', 'performance': '',
        'scalability': '', 'additional': ''
    }

def generate_structured_plan(project_details, model):
    prompt_part1 = f"""
    Create a structured project plan for a {project_details['type']} with the following specifications:

    Project Description: {project_details['description']}
    Target Audience: {project_details['audience']}
    Main Features: {project_details['features']}
    User Interface: {project_details['ui']}
    Data Storage: {project_details['storage']}
    External APIs/Services: {project_details['apis']}
    Performance Requirements: {project_details['performance']}
    Scalability Importance: {project_details['scalability']}
    Additional Requirements: {project_details['additional']}

    Please provide a plan with the following structure:
    1. Project Title
    2. 5-7 main steps, each with:
       - Step title
       - Step description
       - 2-4 substeps for each step, each with:
         * Substep title
         * Substep description
    """

    prompt_part2 = """
    Format the output as a JSON object matching this structure:
    {
        "title": "Project Title",
        "steps": [
            {
                "id": 1,
                "title": "Step 1 Title",
                "description": "Step 1 Description",
                "substeps": [
                    {
                        "id": 1.1,
                        "title": "Substep 1.1 Title",
                        "description": "Substep 1.1 Description"
                    }
                ]
            }
        ]
    }

    Ensure that the response is a valid JSON object and nothing else. Do not include any explanations or text outside of the JSON structure.
    """

    prompt = prompt_part1 + prompt_part2
    response = ollama_api.generate(prompt, model)

    st.write("AI Response (for debugging):")
    st.code(response)

    try:
        # Try to find JSON object in the response
        json_start = response.find('{')
        json_end = response.rfind('}') + 1
        if json_start != -1 and json_end != -1:
            json_str = response[json_start:json_end]
            plan = json.loads(json_str)
        else:
            raise json.JSONDecodeError("No JSON object found", response, 0)

        # Validate the structure of the plan
        if "title" not in plan or "steps" not in plan or not isinstance(plan["steps"], list):
            raise ValueError("Generated plan does not have the correct structure")

        for step in plan['steps']:
            if "id" not in step or "title" not in step or "description" not in step or "substeps" not in step:
                raise ValueError(f"Step {step.get('id', 'unknown')} is missing required fields")
            step['completed'] = False
            for substep in step['substeps']:
                if "id" not in substep or "title" not in substep or "description" not in substep:
                    raise ValueError(f"Substep in step {step['id']} is missing required fields")
                substep['completed'] = False
                substep['context'] = ""
                substep['code'] = ""

        return plan
    except json.JSONDecodeError as e:
        st.error(f"Failed to parse the generated plan. JSON Error: {str(e)}")
        st.error("The AI response was not a valid JSON object. Please try again or adjust the prompt.")
    except ValueError as e:
        st.error(f"Invalid plan structure: {str(e)}")
        st.error("The generated plan did not meet the required structure. Please try again.")
    except Exception as e:
        st.error(f"An unexpected error occurred: {str(e)}")

    return None

def render(config):
    st.title("Project Prompt and Plan Generation")

    if 'current_project' not in st.session_state or 'current_project_path' not in st.session_state:
        st.error("Please select a project from the sidebar first.")
        return

    project_path = Path(st.session_state.current_project_path)
    st.write(f"Current Project: {st.session_state.current_project}")
    st.write(f"Project Path: {project_path}")
    st.write(f"Using AI Model: {config.get('model', 'deepseek-coder-v2')}")

    # Load or initialize project details
    project_details = load_project_details(project_path)

    # Project Details Form
    st.subheader("Project Specification")
    with st.form("project_details_form"):
        project_details['type'] = st.text_input("Project Type", project_details['type'])
        project_details['description'] = st.text_area("Project Description", project_details['description'])
        project_details['audience'] = st.text_input("Target Audience", project_details['audience'])
        project_details['features'] = st.text_area("Main Features", project_details['features'])
        project_details['ui'] = st.selectbox("User Interface", ["", "Command Line", "GUI", "Web-based", "Mobile App", "Other"], index=["", "Command Line", "GUI", "Web-based", "Mobile App", "Other"].index(project_details['ui']))
        project_details['storage'] = st.selectbox("Data Storage", ["", "No", "Local File", "Database", "Cloud Storage"], index=["", "No", "Local File", "Database", "Cloud Storage"].index(project_details['storage']))
        project_details['apis'] = st.text_input("External APIs", project_details['apis'])
        project_details['performance'] = st.text_area("Performance Requirements", project_details['performance'])
        project_details['scalability'] = st.selectbox("Scalability Importance", ["", "Not important", "Somewhat important", "Very important", "Critical"], index=["", "Not important", "Somewhat important", "Very important", "Critical"].index(project_details['scalability']))
        project_details['additional'] = st.text_area("Additional Requirements", project_details['additional'])

        if st.form_submit_button("Save Project Details"):
            save_project_details(project_details, project_path)
            st.success("Project details saved successfully!")

    plan = load_plan_from_file(project_path)

    if plan is None:
        if st.button("Generate Project Plan"):
            with st.spinner("Generating project plan..."):
                plan = generate_structured_plan(project_details, config.get('model', 'deepseek-coder-v2'))
                if plan:
                    save_plan_to_file(plan, project_path)
                    st.success("Project plan generated and saved successfully!")
                    st.session_state.page = "Project Execution"
                    st.experimental_rerun()
                else:
                    st.error("Failed to generate a valid project plan. Please review the error messages above and try again.")
    else:
        st.write("A project plan has already been generated.")
        if st.button("View and Execute Plan"):
            st.session_state.page = "Project Execution"
            st.experimental_rerun()

        if st.button("Update Project Plan"):
            with st.spinner("Updating project plan..."):
                updated_plan = generate_structured_plan(project_details, config.get('model', 'deepseek-coder-v2'))
                if updated_plan:
                    # Preserve completion status of existing steps and substeps
                    for old_step, new_step in zip(plan['steps'], updated_plan['steps']):
                        new_step['completed'] = old_step.get('completed', False)
                        for old_substep, new_substep in zip(old_step['substeps'], new_step['substeps']):
                            new_substep['completed'] = old_substep.get('completed', False)
                            new_substep['context'] = old_substep.get('context', '')
                            new_substep['code'] = old_substep.get('code', '')

                    save_plan_to_file(updated_plan, project_path)
                    st.success("Project plan updated and saved successfully!")
                    st.experimental_rerun()
                else:
                    st.error("Failed to update the project plan. Please review the error messages above and try again.")

    if st.button("View Project Files"):
        st.session_state.page = "Project Files"
        st.experimental_rerun()
